//! Golden test: emitted Ruby conformance harness matches committed
//! `sdks/ruby/test/contract/*.rb` below the `@generated` header.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

mod support;

use std::fs;

use dto_gen::emit_conformance_rb::emit_conformance_rb;
use dto_gen::ir::Ir;







fn emitted_map(ir: &Ir) -> std::collections::BTreeMap<String, String> {
    emit_conformance_rb(ir)
        .expect("emit rb conformance")
        .into_iter()
        .collect()
}

#[test]
fn ruby_conformance_matches_committed() {
    let ir = support::lower_bindings_ir();
    let emitted = emitted_map(&ir);
    let dir = support::paths()
        .generated_path("rbConformance")
        .expect("rbConformance");
    assert!(!emitted.is_empty(), "emitter returned no files");
    for (name, contents) in &emitted {
        assert!(
            contents.contains("@generated by dto-gen"),
            "{name} missing generated header"
        );
        let committed = fs::read_to_string(dir.join(name))
            .unwrap_or_else(|e| panic!("read committed {name}: {e}"));
        assert_eq!(
            support::strip_generated_header(contents),
            support::strip_generated_header(&committed),
            "ruby conformance {name} drifted — regenerate with --rb-conformance-out"
        );
    }
    let committed_rb: Vec<_> = fs::read_dir(&dir)
        .expect("read contract dir")
        .filter_map(|entry| {
            let entry = entry.ok()?;
            let name = entry.file_name().into_string().ok()?;
            name.ends_with(".rb").then_some(name)
        })
        .collect();
    for name in committed_rb {
        assert!(
            emitted.contains_key(&name),
            "emitter omitted committed file {name}"
        );
    }
}

#[test]
fn ruby_conformance_emit_is_byte_idempotent() {
    let ir = support::lower_bindings_ir();
    let first = emit_conformance_rb(&ir).expect("first");
    let second = emit_conformance_rb(&ir).expect("second");
    assert_eq!(first, second);
}
